"""Bytewax is a Python framework for building scalable dataflows."""

from importlib.metadata import PackageNotFoundError, version

try:
    from ._build_info import __git_dirty__, __git_revision__, __version__
except ImportError:  # pragma: no cover
    # `_build_info.py` is generated by `build.rs` during the build.
    # It is missing when running from a source checkout that has not
    # been built yet.
    __git_revision__ = "unknown"
    __git_dirty__ = False
    try:
        __version__ = version("bytewax")
    except PackageNotFoundError:
        # The package metadata is unavailable, e.g. when running from
        # a source checkout that has not been installed yet.
        __version__ = "unknown"

__all__ = ["__git_dirty__", "__git_revision__", "__version__"]
